export type ThemeMode = 'system' | 'light' | 'dark';

export type TabId = 'heute' | 'woche' | 'einstellungen';

const WEEKDAYS_SHORT = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'];

export function dateKey(d: Date): string {
  const y = d.getFullYear();
  const m = `${d.getMonth() + 1}`.padStart(2, '0');
  const day = `${d.getDate()}`.padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export function todayKey(): string {
  return dateKey(new Date());
}

export function addDays(d: Date, n: number): Date {
  const copy = new Date(d);
  copy.setDate(copy.getDate() + n);
  return copy;
}

export function lastNDays(count: number): Date[] {
  const result: Date[] = [];
  for (let i = count - 1; i >= 0; i -= 1) {
    result.push(addDays(new Date(), -i));
  }
  return result;
}

const fullFormatter = new Intl.DateTimeFormat('de-DE', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});

export function formatDate(d: Date = new Date()): string {
  return fullFormatter.format(d);
}

export function weekdayShort(d: Date): string {
  return WEEKDAYS_SHORT[d.getDay()] ?? 'So';
}

export function moodLabel(value: number): string {
  switch (value) {
    case 1:
      return 'Schlecht';
    case 2:
      return 'Eher schlecht';
    case 3:
      return 'Okay';
    case 4:
      return 'Gut';
    case 5:
      return 'Sehr gut';
    default:
      return '';
  }
}

import { addDays, dateKey } from './date';

export interface StreakInfo {
  current: number;
  longest: number;
}

function parseKey(key: string): Date {
  const y = Number(key.slice(0, 4));
  const m = Number(key.slice(5, 7));
  const d = Number(key.slice(8, 10));
  return new Date(y, (m || 1) - 1, d || 1);
}

export function computeStreak(dates: Set<string>): StreakInfo {
  let current = 0;
  if (dates.size > 0) {
    const today = new Date();
    let cursor = new Date(today);
    if (!dates.has(dateKey(cursor))) {
      cursor = addDays(cursor, -1);
    }
    while (dates.has(dateKey(cursor))) {
      current += 1;
      cursor = addDays(cursor, -1);
    }
  }

  const sorted = [...dates].sort();
  let longest = 0;
  let run = 0;
  let prev: Date | null = null;
  for (const key of sorted) {
    const currentDate = parseKey(key);
    const daysBetween =
      prev === null ? 0 : Math.round((currentDate.getTime() - prev.getTime()) / 86400000);
    run = prev === null || daysBetween !== 1 ? 1 : run + 1;
    if (run > longest) {
      longest = run;
    }
    prev = currentDate;
  }

  return { current, longest };
}

