}

import { openDB, type DBSchema, type IDBPDatabase } from 'idb';
import type { Habit, HabitEntry, MoodEntry } from './types';

const DB_NAME = 'rhythm';
const DB_VERSION = 1;

export interface RhythmDB extends DBSchema {
  habits: Habit;
  entries: HabitEntry;
  moods: MoodEntry;
}

let dbPromise: Promise<IDBPDatabase<RhythmDB>> | null = null;

function openDb(): Promise<IDBPDatabase<RhythmDB>> {
  if (!dbPromise) {
    dbPromise = openDB<RhythmDB>(DB_NAME, DB_VERSION, (db) => {
      db.createObjectStore('habits', { keyPath: 'id' });
      db.createObjectStore('entries', { keyPath: 'id' });
      db.createObjectStore('moods', { keyPath: 'date' });
    });
  }
  return dbPromise;
}

export async function getHabits(): Promise<Habit[]> {
  const db = await openDb();
  return db.getAll('habits');
}

export async function putHabit(habit: Habit): Promise<void> {
  const db = await openDb();
  await db.put('habits', habit, habit.id);
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await openDb();
  await db.delete('habits', id);
  const entries = await db.getAll('entries');
  await Promise.all(
    entries.filter((e) => e.habitId === id).map((e) => db.delete('entries', e.id)),
  );
}

export async function getAllEntries(): Promise<HabitEntry[]> {
  const db = await openDb();
  return db.getAll('entries');
}

export async function putEntry(entry: HabitEntry): Promise<void> {
  const db = await openDb();
  await db.put('entries', entry, entry.id);
}

export async function deleteEntry(id: string): Promise<void> {
  const db = await openDb();
  await db.delete('entries', id);
}

export async function getMoods(): Promise<MoodEntry[]> {
  const db = await openDb();
  return db.getAll('moods');
}

export async function saveMood(mood: MoodEntry): Promise<void> {
  const db = await openDb();
  await db.put('moods', mood, mood.date);
}

export async function clearDatabase(): Promise<void> {
  const db = await openDb();
  await db.clear('habits');
  await db.clear('entries');
  await db.clear('moods');
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from 'react';
import type { ThemeMode } from './types';

export type ResolvedTheme = 'light' | 'dark';

interface ThemeContextValue {
  theme: ThemeMode;
  resolved: ResolvedTheme;
  setTheme: (theme: ThemeMode) => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

const STORAGE_KEY = 'rhythm-theme';

function initialTheme(): ThemeMode {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'light' || stored === 'dark' || stored === 'system') {
      return stored;
    }
  } catch {
    // localStorage nicht verfügbar – Standardwert verwenden
  }
  return 'system';
}

function systemTheme(): ResolvedTheme {
  if (typeof window === 'undefined') return 'light';
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setThemeState] = useState<ThemeMode>(initialTheme);
  const [resolved, setResolved] = useState<ResolvedTheme>(systemTheme);

  useEffect(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)');
    const apply = () => {
      const next = theme === 'system' ? systemTheme() : theme;
      setResolved(next);
      const root = document.documentElement;
      root.classList.toggle('dark', next === 'dark');
      root.style.colorScheme = next;
    };
    apply();
    if (typeof media.addEventListener === 'function') {
      media.addEventListener('change', apply);
      return () => media.removeEventListener('change', apply);
    }
    media.addListener(apply);
    return () => media.removeListener(apply);
  }, [theme]);

  const setTheme = (next: ThemeMode) => {
    setThemeState(next);
    try {
      localStorage.setItem(STORAGE_KEY, next);
    } catch {
      // ignore
    }
  };

  return <ThemeContext.Provider value={{ theme, resolved, setTheme }}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);
  if (!ctx) {
    throw new Error('useTheme muss innerhalb von ThemeProvider verwendet werden');
  }
  return ctx;
}

