import { useEffect, useState } from 'react';
import { IconPlus, IconPencil } from '../components/icons';
import HabitCard from '../components/HabitCard';
import HabitComposer from '../components/HabitComposer';
import MoodSelector from '../components/MoodSelector';
import { useAppData, type NewHabitData } from '../hooks/useAppData';
import { computeStreak } from '../lib/streaks';
import { formatDate, todayKey } from '../lib/date';
import type { Habit } from '../lib/types';

export default function TodayScreen() {
  const {
    habits,
    loading,
    mood,
    isDone,
    datesByHabit,
    toggleHabit,
    addHabit,
    updateHabit,
    deleteHabit,
    saveMood,
  } = useAppData();

  const [composerOpen, setComposerOpen] = useState(false);
  const [editingHabit, setEditingHabit] = useState<Habit | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [moodValue, setMoodValue] = useState<number | undefined>(mood?.value);
  const [moodNote, setMoodNote] = useState(mood?.note);

  useEffect(() => {
    setMoodValue(mood?.value);
    setMoodNote(mood?.note);
  }, [mood]);

  const today = todayKey();
  const doneCount = habits.filter((h) => isDone(h.id, today)).length;
  const remaining = habits.length - doneCount;

  const openAdd = () => {
    setEditingHabit(null);
    setComposerOpen(true);
  };

  const openEdit = (habit: Habit) => {
    setEditingHabit(habit);
    setComposerOpen(true);
  };

  const closeComposer = () => {
    setComposerOpen(false);
    setEditingHabit(null);
  };

  const handleSave = (data: NewHabitData) => {
    if (editingHabit) {
      updateHabit(editingHabit.id, data);
    } else {
      addHabit(data);
    }
    closeComposer();
  };

  const handleMoodChange = (value: number) => {
    setMoodValue(value);
    saveMood(value, moodNote);
  };

  const handleNoteChange = (note: string) => {
    setMoodNote(note);
    saveMood(moodValue ?? 3, note);
  };

  const progress = habits.length > 0 ? doneCount / habits.length : 0;

  return (
    <div>
      <header className="flex items-start justify-between gap-4">
        <div>
          <h1 className="font-serif text-3xl tracking-[-0.02em] text-ink">rhythm</h1>
          <p className="mt-2 text-sm text-muted">{formatDate()}</p>
        </div>
        <button
          type="button"
          onClick={openAdd}
          className="flex h-11 shrink-0 items-center gap-2 rounded-lg border border-border px-3 text-sm font-medium text-ink transition-colors hover:bg-surface-2 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink"
        >
          <IconPencil className="h-5 w-5" />
          Verwalten
        </button>
      </header>

      {loading ? (
        <p className="mt-8 text-sm text-muted">Lade deine Daten …</p>
      ) : habits.length > 0 ? (
        <section className="mt-8" aria-label="Heutige Fortschritt">
          <h2 className="font-serif text-4xl tracking-[-0.02em] text-ink">
            {doneCount} von {habits.length}
          </h2>
          <div className="mt-3 h-1 w-full overflow-hidden bg-surface-2">
            <div className="h-full bg-accent" style={{ width: `${progress * 100}%` }} />
          </div>
          <p className="mt-2 text-sm text-muted">
            {remaining > 0 ? `${remaining} offen` : 'Alle Habits erledigt.'}
          </p>
        </section>
      ) : (
        <section className="mt-8" aria-label="Willkommen">
          <h2 className="font-serif text-4xl tracking-[-0.02em] text-ink">Willkommen.</h2>
          <p className="mt-2 text-sm text-muted">Lege deinen ersten Habit an, um loszulegen.</p>
        </section>
      )}

      <section className="mt-8" aria-label="Stimmung heute">
        <MoodSelector value={moodValue} note={moodNote} onChange={handleMoodChange} onNoteChange={handleNoteChange} />
      </section>

      {!loading && habits.length > 0 ? (
        <ul className="mt-6 space-y-3">
          {habits.map((habit) => (
            <li key={habit.id}>
              <HabitCard
                habit={habit}
                done={isDone(habit.id, today)}
                streak={computeStreak(datesByHabit.get(habit.id) ?? new Set<string>())}
                editing={editingId === habit.id}
                onToggle={toggleHabit}
                onEdit={setEditingId}
                onUpdate={updateHabit}
                onDelete={deleteHabit}
              />
            </li>
          ))}
        </ul>
      ) : null}

      {!loading && habits.length > 0 ? (
        <button
          type="button"
          onClick={openAdd}
          className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-ink/20 py-12 text-sm font-medium text-muted transition-colors hover:border-ink/40 hover:text-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink"
        >
          <IconPlus className="h-5 w-5" />
          Habit anlegen
        </button>
      ) : null}

      {composerOpen ? <HabitComposer habit={editingHabit} onClose={closeComposer} onSave={handleSave} /> : null}
    </div>
  );
}

import MoodChart, { WeekChart, type WeekDayPoint } from '../components/WeekChart';
import { useAppData } from '../hooks/useAppData';
import { dateKey, lastNDays } from '../lib/date';

export default function WeekScreen() {
  const { habits, moods, isDone } = useAppData();
  const days = lastNDays(7);

  const data: WeekDayPoint[] = days.map((d) => {
    const key = dateKey(d);
    const moodEntry = moods.find((m) => m.date === key);
    return {
      key,
      done: habits.filter((h) => isDone(h.id, key)).length,
      mood: moodEntry?.value,
    };
  });

  return (
    <div>
      <header className="mt-2">
        <h1 className="font-serif text-3xl tracking-[-0.02em] text-ink">Diese Woche</h1>
        <p className="mt-1 text-sm text-muted">Die letzten sieben Tage.</p>
      </header>

      <section className="mt-6 rounded-xl border border-border bg-surface p-5" aria-label="Erledigte Habits">
        <h2 className="font-serif text-xl text-ink">Erledigte</h2>
        <p className="mt-1 text-sm text-muted">Wie viele Habits du pro Tag geschafft hast.</p>
        <div className="mt-4">
          <WeekChart data={data} />
        </div>
      </section>

      <section className="mt-5 rounded-xl border border-border bg-surface p-5" aria-label="Stimmung">
        <h2 className="font-serif text-xl text-ink">Stimmung</h2>
        <p className="mt-1 text-sm text-muted">Wie es dir in den letzten Tagen ergangen ist.</p>
        <div className="mt-4">
          <MoodChart data={data} />
        </div>
      </section>
    </div>
  );
}

import { useState } from 'react';
import { useTheme } from '../lib/theme';
import { useAppData } from '../hooks/useAppData';
import type { ThemeMode } from '../lib/types';

const THEME_OPTIONS: ReadonlyArray<{ id: ThemeMode; label: string }> = [
  { id: 'light', label: 'Hell' },
  { id: 'auto', label: 'Auto' },
  { id: 'dark', label: 'Dunkel' },
];

export default function SettingsScreen() {
  const { theme, resolved, setTheme } = useTheme();
  const { clearAll } = useAppData();
  const [confirming, setConfirming] = useState(false);
  const online = typeof navigator === 'undefined' ? true : navigator.onLine;

  const themeLabel = theme === 'system' ? 'Automatisch' : resolved === 'dark' ? 'Dunkel' : 'Hell';

  const handleClearAll = () => {
    clearAll();
    setConfirming(false);
  };

  return (
    <div className="space-y-5">
      <section className="rounded-xl border border-border bg-surface p-5" aria-label="Design">
        <h2 className="font-serif text-xl text-ink">Erscheinung</h2>
        <p className="mt-1 text-sm text-muted">Für dieses Gerät gespeichert.</p>
        <div className="mt-4 flex rounded-lg border border-border p-1" role="group" aria-label="Design wählen">
          {THEME_OPTIONS.map((option) => {
            const active = theme === option.id;
            return (
              <button
                key={option.id}
                type="button"
                onClick={() => setTheme(option.id)}
                aria-pressed={active}
                className={`flex-1 rounded-md py-2.5 text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink ${
                  active ? 'bg-ink text-canvas' : 'text-muted hover:text-ink'
                }`}
              >
                {option.label}
              </button>
            );
          })}
        </div>
        <p className="mt-3 text-xs text-muted">Aktuell: {themeLabel}</p>
      </section>

      <section className="rounded-xl border border-border bg-surface p-5" aria-label="Offline">
        <h2 className="font-serif text-xl text-ink">Offline</h2>
        <p className="mt-2 text-sm text-muted">
          Rhythm funktioniert vollständig offline. Alle Daten liegen in deinem Browser und werden nicht auf einem Server
          gesichert.
        </p>
        <p className="mt-2 text-sm text-ink">Status: {online ? 'Online' : 'Offline'}</p>
      </section>

      <section className="rounded-xl border border-border bg-surface p-5" aria-label="Daten">
        <h2 className="font-serif text-xl text-ink">Daten</h2>
        <p className="mt-1 text-sm text-muted">
          Alle Habits, Erledigungen und Stimmungen werden dauerhaft aus diesem Browser gelöscht.
        </p>
        {confirming ? (
          <div className="mt-4 flex gap-2">
            <button
              type="button"
              onClick={handleClearAll}
              className="flex-1 rounded-lg bg-ink py-3 text-sm font-medium text-canvas focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink"
            >
              Wirklich löschen
            </button>
            <button
              type="button"
              onClick={() => setConfirming(false)}
              className="flex-1 rounded-lg border border-border py-3 text-sm font-medium text-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink"
            >
              Abbrechen
            </button>
          </div>
        ) : (
          <button
            type="button"
            onClick={() => setConfirming(true)}
            className="mt-4 rounded-lg border border-[#9f2f2d]/40 py-3 text-sm font-medium text-[#9f2f2d] transition-colors hover:bg-[#fdebec] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink"
          >
            Alle Daten löschen
          </button>
        )}
      </section>
    </div>
  );
}

