import type { TabId } from './lib/types';

function Shell() {
  const [tab, setTab] = useState<TabId>('heute');
  const { needRefresh } = useRegisterSW({
    onRegistered: () => undefined,
    onRegisterError: () => undefined,
  });

  return (
